import { useState, FormEvent } from 'react';
import {
  Card,
  Stack,
  TextField,
  Select,
  SelectOption,
  Switch,
  Button,
  Label,
} from '@jinx-ui/react';

type Language = 'ru' | 'en';

interface ProfileSettings {
  name: string;
  language: Language;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  onSave: (settings: ProfileSettings) => void;
}

const ProfileSettingsForm = ({ onSave }: ProfileSettingsFormProps) => {
  const [name, setName] = useState('');
  const [language, setLanguage] = useState<Language>('ru');
  const [emailNotifications, setEmailNotifications] = useState(false);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name, language, emailNotifications });
  };

  return (
    <Card className="jx-p-6">
      <form onSubmit={handleSubmit}>
        <Stack direction="column" gap="4">
          <Stack direction="column" gap="1">
            <Label htmlFor="profile-name">Имя</Label>
            <TextField
              id="profile-name"
              value={name}
              onChange={(value: string) => setName(value)}
              placeholder="Введите имя"
            />
          </Stack>

          <Stack direction="column" gap="1">
            <Label htmlFor="profile-language">Язык интерфейса</Label>
            <Select
              id="profile-language"
              value={language}
              onChange={(value: string) => setLanguage(value as Language)}
            >
              <SelectOption value="ru">Русский</SelectOption>
              <SelectOption value="en">English</SelectOption>
            </Select>
          </Stack>

          <Stack direction="row" align="center" justify="between">
            <Label htmlFor="profile-email-notifications">
              Уведомления на почту
            </Label>
            <Switch
              id="profile-email-notifications"
              checked={emailNotifications}
              onChange={(checked: boolean) => setEmailNotifications(checked)}
            />
          </Stack>

          <Button type="submit" variant="primary">
            Сохранить
          </Button>
        </Stack>
      </form>
    </Card>
  );
};

export default ProfileSettingsForm;

